mapper.select:
SELECT d.drug_name_chinese AS drugName, d.drug_name AS drugNameEn, dis.disease_name_chinese AS disease, a.direct_target_or_not AS directTarget, et.evidence_type_chinese AS evidenceType, er.evidence_ranking_chinese AS evidenceRanking, ep.evidence_phase_chinese AS evidencePhase, r.relationship_chinese AS relationship, a.annotation_chinese AS annotation, a.comment AS comment FROM nkb.variant_drug_annotation a JOIN nkb.gene_variant gv ON gv.gene_variant_id = a.gene_variant_id LEFT JOIN nkb.drug d ON d.drug_id = a.drug_id LEFT JOIN nkb.disease dis ON dis.do_id = a.disease_id LEFT JOIN nkb.evidence_type et ON et.evidence_type_id = a.evidence_type_id LEFT JOIN nkb.evidence_ranking er ON er.evidence_ranking_id = a.evidence_ranking_id LEFT JOIN nkb.evidence_phase ep ON ep.evidence_phase_id = a.evidence_phase_id LEFT JOIN nkb.relationship r ON r.relationship_id = a.relationship_id WHERE a.gene_variant_id IN #{gvId}
AND a.disease_id IN #{dId}
ORDER BY er.evidence_ranking_id, a.annotation_id LIMIT #{limit}
